import { nextPhase } from '@runcastle/core'
import type { EventRow, Phase } from '@runcastle/core'
import type { BranchList, FeatureFull, FeatureListItem } from './api'

/**
 * The New Feature form's default base branch. A new feature forks off the branch
 * the user is currently on — that's the branch they chose to work on, and burns
 * never touch the checkout. Fall back to the project main branch when the current
 * checkout isn't a selectable base: a detached HEAD, or a test drive holding
 * runcastle itself on a `feature/*` branch (which the picker excludes).
 */
export function defaultBaseBranch(
  data: Pick<BranchList, 'current' | 'mainBranch' | 'branches'>,
): string {
  return data.branches.includes(data.current) ? data.current : data.mainBranch
}

/**
 * Client-side feature derivations (UI-SPEC §2/§3): sidebar glyph, needs-me
 * classification, and the overview primary-action state machine. Pure functions
 * over wire data — no IO.
 */

export const PHASE_ORDER: Phase[] = [
  'ideation',
  'spec',
  'tickets',
  'implementation',
  'review',
  'shipped',
]

/** Sidebar status glyph per phase (mono). */
export function phaseGlyph(phase: Phase): string {
  switch (phase) {
    case 'ideation':
      return '◉'
    case 'spec':
      return '◐'
    case 'tickets':
      return '▤'
    case 'implementation':
      return '⚙'
    case 'review':
      return '◆'
    case 'shipped':
      return '✓'
  }
}

export type NeedsMeKind = 'grill' | 'burn' | 'attention' | 'ship'

export interface NeedsMe {
  kind: NeedsMeKind
  label: string
}

/**
 * Which features need me (UI-SPEC §2). Computed from `feature.list` data:
 * feature phase + ticket counts + active-run flag. A failed run leaves failed
 * tickets, so `ticketCounts.failed` is the list-level proxy for "run failed".
 *
 * Note: "ideation & no-live-session" — `feature.list` omits sessions, so the
 * grilling dot shows for any active ideation feature; the live-session nuance is
 * reflected in the overview primary action (which uses full `feature.get` data).
 */
export function needsMe(f: FeatureListItem): NeedsMe | null {
  if (f.status === 'shipped' || f.status === 'archived') return null
  if (f.activeRun) return null // burning: shown as a spinner, not a needs-me dot
  if (f.ticketCounts.failed > 0)
    return { kind: 'attention', label: 'run failed — needs attention' }
  if (f.phase === 'ideation') return { kind: 'grill', label: 'needs grilling' }
  if (f.phase === 'tickets' && f.ticketCounts.total > 0)
    return { kind: 'burn', label: 'review & burn tickets' }
  if (f.phase === 'review') return { kind: 'ship', label: 'test & merge' }
  return null
}

/** Sidebar sort: needs-me first, then active, then shipped (dimmed). Stable
 *  within groups (the server returns newest-first). */
export function sortForSidebar(features: FeatureListItem[]): FeatureListItem[] {
  const rank = (f: FeatureListItem): number => {
    if (f.status === 'shipped') return 2
    if (needsMe(f)) return 0
    return 1
  }
  return [...features]
    .map((f, i) => ({ f, i }))
    .sort((a, b) => rank(a.f) - rank(b.f) || a.i - b.i)
    .map((x) => x.f)
}

// --- overview primary-action state machine (UI-SPEC §3) --------------------

export type PrimaryActionKind =
  | 'startGrill'
  | 'openGrill'
  | 'reviewTickets'
  | 'startBurn'
  | 'watchRun'
  | 'testDrive'
  | 'merge'
  | 'askQuestions'

export interface PrimaryAction {
  kind: PrimaryActionKind
  label: string
  /** Session to focus for `openGrill`. */
  sessionId?: string
  /** Run to focus for `watchRun`. */
  runId?: string
}

/**
 * The single solid button on the overview (UI-SPEC §3):
 * Start grilling → Open live grill → Review tickets → (Burn in tickets tab) →
 * Watch run → Merge → Ask questions. Test driving at `review` is optional and
 * lives as a secondary action, so the primary here no longer depends on it.
 */
export function primaryAction(full: FeatureFull): PrimaryAction {
  const { feature, sessions, runs } = full
  const liveSession = sessions.find((s) => s.status === 'live')

  switch (feature.phase) {
    case 'ideation':
    case 'spec':
      return liveSession
        ? { kind: 'openGrill', label: 'Open live grill', sessionId: liveSession.id }
        : { kind: 'startGrill', label: 'Start grilling' }
    case 'tickets':
      return { kind: 'reviewTickets', label: 'Review tickets' }
    case 'implementation': {
      const run = latestRun(runs)
      // A live run → watch it. No active run means the burn was cancelled or
      // crashed (or G3 was overridden without starting one): offer to (re)start
      // the burn so the feature never dead-ends at `implementation`.
      if (run && run.status === 'running') {
        return { kind: 'watchRun', label: 'Watch run', runId: run.id }
      }
      return { kind: 'startBurn', label: 'Start burn' }
    }
    case 'review':
      // Merge is the primary action whether or not a test drive is active — the
      // server stops an active drive of this feature before merging. Test driving
      // first is optional (offered as a secondary action on the overview).
      return { kind: 'merge', label: 'Merge' }
    case 'shipped':
      return { kind: 'askQuestions', label: 'Ask questions' }
  }
}

/** One-line state summary shown above the primary action (UI-SPEC §3). */
export function stateSummary(full: FeatureFull, driving: boolean): string {
  const { feature, tickets, sessions, runs } = full
  const live = sessions.some((s) => s.status === 'live')
  const t = tickets.length
  const done = tickets.filter((x) => x.status === 'done').length
  const failed = tickets.filter((x) => x.status === 'failed').length
  switch (feature.phase) {
    case 'ideation':
      return live
        ? 'Grilling in progress — decisions accumulate in Knowledge.'
        : 'Grill the agent to capture decisions and shape the work.'
    case 'spec':
      return live ? 'Writing the spec beside the conversation.' : 'Spec in progress.'
    case 'tickets':
      return `${t} ticket${t === 1 ? '' : 's'} ready — review, then burn.`
    case 'implementation': {
      const run = latestRun(runs)
      // Only claim a burn is in progress when a run is actually running —
      // otherwise be honest that it hasn't started / was cancelled.
      if (!run) return `Burn not started — ${t} ticket${t === 1 ? '' : 's'} ready. Start the burn.`
      if (run.status === 'running') {
        return `Burning ${t} ticket${t === 1 ? '' : 's'} — ${done} done${failed ? `, ${failed} failed` : ''}.`
      }
      if (run.status === 'cancelled') return 'Run cancelled — start the burn to retry.'
      if (run.status === 'failed') return 'Run failed — start the burn to retry.'
      return `Burn not started — ${t} ticket${t === 1 ? '' : 's'} ready. Start the burn.`
    }
    case 'review':
      if (driving) return 'Test driving the branch — merge when it looks right.'
      return failed
        ? `Run finished with ${failed} failed ticket${failed === 1 ? '' : 's'} — review, then ship.`
        : 'Run complete — merge to ship, or test drive it first.'
    case 'shipped':
      return 'Shipped. Ask questions anytime.'
  }
}

function latestRun(runs: FeatureFull['runs']): FeatureFull['runs'][number] | undefined {
  if (runs.length === 0) return undefined
  return [...runs].sort((a, b) => b.startedAt - a.startedAt)[0]
}

export { latestRun }

// ===========================================================================
// app-redesign derivations — pipeline-first shell (triage sidebar, workspace
// pipeline stepper, guided next-step bar). Pure functions over wire data.
// ===========================================================================

export const PHASE_LABELS: Record<Phase, string> = {
  ideation: 'ideation',
  spec: 'spec',
  tickets: 'tickets',
  implementation: 'build',
  review: 'review',
  shipped: 'shipped',
}

/** One-line tooltip per phase for the pipeline stepper. */
export const PHASE_TIP: Record<Phase, string> = {
  ideation: 'Shape the idea in a grill session',
  spec: 'Write it up as a spec',
  tickets: 'Break the work into atomic tickets',
  implementation: 'Burn the tickets into commits',
  review: 'Test-drive the branch, then merge',
  shipped: 'Merged to the main branch',
}

export function phaseIndex(phase: Phase): number {
  return PHASE_ORDER.indexOf(phase)
}

// --- triage sidebar --------------------------------------------------------

export type TriageKey = 'needsYou' | 'agentWorking' | 'inProgress' | 'shipped' | 'archived'

export interface TriageGroup {
  key: TriageKey
  label: string
  features: FeatureListItem[]
}

/**
 * Which triage lane a feature belongs to. Order of checks matters — the first
 * match wins. Archived wins over everything: an archived feature carries no
 * needs-me / working state, it only sits in the archived lane.
 */
export function triageOf(f: FeatureListItem): TriageKey {
  if (f.status === 'archived') return 'archived'
  if (f.status === 'shipped') return 'shipped'
  if (f.activeRun) return 'agentWorking'
  if (needsMe(f)) return 'needsYou'
  return 'inProgress'
}

/**
 * Group features into the sidebar's triage lanes (app-redesign). Preserves the
 * incoming order within each lane (the server returns newest-first). Empty lanes
 * are omitted; lanes are returned in display order. Archived features are
 * excluded from the default view (decision #8) — pass `showArchived` to surface
 * them in a trailing Archived lane.
 */
export function triage(
  features: FeatureListItem[],
  opts: { showArchived?: boolean } = {},
): TriageGroup[] {
  const buckets: Record<TriageKey, FeatureListItem[]> = {
    needsYou: [],
    agentWorking: [],
    inProgress: [],
    shipped: [],
    archived: [],
  }
  for (const f of features) buckets[triageOf(f)].push(f)

  const order: { key: TriageKey; label: string }[] = [
    { key: 'needsYou', label: 'Needs you' },
    { key: 'agentWorking', label: 'Agent working' },
    { key: 'inProgress', label: 'In progress' },
    { key: 'shipped', label: 'Shipped' },
  ]
  if (opts.showArchived) order.push({ key: 'archived', label: 'Archived' })
  return order
    .map(({ key, label }) => ({ key, label, features: buckets[key] }))
    .filter((g) => g.features.length > 0)
}

// --- pipeline (sidebar mini-map + workspace stepper) -----------------------

export type StepState = 'done' | 'current' | 'upcoming'

export interface PipelineStep {
  phase: Phase
  label: string
  state: StepState
  /** The phase currently shown in the workspace (viewed pin or live phase). */
  isViewed: boolean
  /** Whether clicking the step navigates (done or current phases only). */
  clickable: boolean
  tip: string
}

function stepState(feature: { phase: Phase }, phase: Phase): StepState {
  const ci = phaseIndex(feature.phase)
  const pi = phaseIndex(phase)
  if (pi < ci) return 'done'
  if (pi === ci) return 'current'
  return 'upcoming'
}

/** Compact 6-segment lifecycle map for a sidebar row. */
export function miniSegments(
  feature: { phase: Phase },
): { phase: Phase; state: StepState }[] {
  return PHASE_ORDER.map((phase) => ({ phase, state: stepState(feature, phase) }))
}

/** The phase actually shown in the workspace (pinned view, else the live phase). */
export function effectivePhase(
  feature: { phase: Phase },
  viewedPhase: Phase | null,
): Phase {
  return viewedPhase ?? feature.phase
}

/** Viewing an earlier, completed phase (workspace is read-only). */
export function isReadonlyView(feature: { phase: Phase }, effective: Phase): boolean {
  return phaseIndex(effective) < phaseIndex(feature.phase)
}

/** The full workspace pipeline stepper for a feature at a given viewed phase. */
export function pipelineSteps(
  feature: { phase: Phase },
  effective: Phase,
): PipelineStep[] {
  return PHASE_ORDER.map((phase) => {
    const state = stepState(feature, phase)
    return {
      phase,
      label: PHASE_LABELS[phase],
      state,
      isViewed: phase === effective,
      clickable: state === 'done' || state === 'current',
      tip: PHASE_TIP[phase],
    }
  })
}

// --- guided next-step bar ---------------------------------------------------

export type ActionKind =
  | 'startGrill' // launchSession { kind: 'ideation' }
  | 'openGrill' // focus the live session in the body
  | 'advance' // feature.advance (crosses non-human gates G1/G2/G4)
  | 'burn' // feature.burn (G3, and resume a parked run)
  | 'cancelRun' // run.cancel
  | 'testDriveStart' // feature.testDrive { action: 'start' }
  | 'testDriveStop' // feature.testDrive { action: 'stop' }
  | 'merge' // feature.merge (G5)
  | 'askQuestions' // launchSession { kind: 'qa' }
  | 'revisit' // launchSession { kind: 'revisit' } — resume the old conversation, amend docs + tickets
  | 'unarchive' // feature.unarchive — restore an archived feature to its lane (next-step bar)

export interface NextAction {
  label: string
  kind: ActionKind
  danger?: boolean
}

export interface NextStep {
  /** Small tracked kicker above the title (e.g. NEXT STEP / IN PROGRESS). */
  kick: string
  title: string
  desc: string
  primary?: NextAction
  secondary: NextAction[]
  /** A run is actively burning — show a spinner in the bar. */
  busy: boolean
}

/**
 * The kickoff line for a review-phase Iterate session (CONTEXT decision #6).
 * Passed as the `launchSession` override (ticket 3 mechanism) when the review
 * bar's Iterate action launches a `revisit` session, so the agent opens on the
 * review-iteration move rather than the generic revisit prompt: read the run
 * outcome + ticket states, interview the human about what the test drive
 * surfaced, emit fix tickets, and never advance the phase.
 */
export const REVIEW_ITERATE_KICKOFF =
  'Proceed with your task: invoke the /runcastle:revisit skill for a REVIEW ITERATION. ' +
  'Call get_feature_context to read the latest run outcome and every ticket’s state, then ' +
  'interview me about what the test drive surfaced — bugs, rough edges, tweaks. Turn what we ' +
  'settle on into fix tickets with emit_tickets, and use update_ticket / cancel_ticket on any ' +
  'stale pending tickets. Never call complete_phase — leave the phase at review. When the ' +
  'tickets are ready, tell me to review the cards and click Burn.'

/**
 * Kickoff line for a review-phase Iterate session opened to RESOLVE a merge
 * conflict (CONTEXT decision #9). Passed as the `launchSession` override, so the
 * revisit agent — whose cwd IS the talk worktree checked out on the feature
 * branch — opens straight on the merge-into-feature resolution rather than the
 * generic revisit prompt. Parameterized with the base branch, feature branch,
 * and conflicting files carried on the `merge.conflict` event.
 */
export function mergeConflictKickoff(base: string, branch: string, files: string[]): string {
  const list = files.length ? files.join(', ') : '(run git status to see the conflicts)'
  return (
    `Proceed with your task: RESOLVE A MERGE CONFLICT. Merging ${base} into ${branch} conflicts ` +
    `on: ${list}. Your working directory IS the talk worktree, already checked out on ${branch}. ` +
    `Run \`git merge ${base}\`, then resolve every conflict using this feature’s spec.md and ` +
    `decisions.md for intent, and commit the merge. Do NOT push and do NOT advance the phase ` +
    `(never call complete_phase). When the merge commit is in, tell me to click “Merge & ship” ` +
    `again for a clean retry.`
  )
}

export interface MergeConflictState {
  /** The base branch that failed to merge in (the merge target). */
  base: string
  /** Repo-relative paths that conflicted. */
  files: string[]
}

/**
 * The standing (unresolved) merge conflict for a feature, derived from its event
 * feed so the review conflict card survives a page reload. The latest
 * `merge.conflict` event carries the base branch + conflicting files; a later
 * `burn.started` supersedes it — burning re-runs implementation and the recorded
 * file list no longer applies, so the card clears once the loop moves on.
 * Returns null when there is no standing conflict. `events` must be in id order.
 */
export function unresolvedMergeConflict(events: EventRow[]): MergeConflictState | null {
  let conflict: MergeConflictState | null = null
  for (const e of events) {
    if (e.type === 'merge.conflict') {
      const d = (e.data ?? {}) as { base?: unknown; files?: unknown }
      const files = Array.isArray(d.files) ? d.files.filter((f): f is string => typeof f === 'string') : []
      conflict = { base: typeof d.base === 'string' ? d.base : '', files }
    } else if (e.type === 'burn.started') {
      conflict = null
    }
  }
  return conflict
}

/**
 * The single guided next step for a feature's *current* phase (app-redesign).
 * Gate-aware: when the gate guarding the next phase is satisfied and crossable
 * without a human-only gate (G3 Burn / G5 Merge), the primary action becomes the
 * promotion; otherwise it's the work action for this phase (grill / burn / …).
 *
 * This supersedes {@link primaryAction} + {@link stateSummary} for the redesign,
 * but reuses the same wire data.
 */
/**
 * True when the feature has an ENDED session of `kind` whose Claude Code
 * conversation can still be picked up (it reached `live`, so it recorded a
 * `ccSessionId`). Opening a terminal of that kind `--resume`s the latest such
 * conversation server-side, so this only decides the WORDING — Resume vs Start —
 * never the action. A terminal is a real process, so quitting runcastle ends
 * every session row; without this the bar would keep saying "Start" for a
 * conversation that is actually being continued.
 */
function hasResumable(sessions: FeatureFull['sessions'], kind: string): boolean {
  return sessions.some((s) => s.kind === kind && s.status === 'ended' && !!s.ccSessionId)
}

export function nextStep(full: FeatureFull, ctx: { driving: boolean }): NextStep {
  const { feature, tickets, sessions, runs, gate } = full
  const live = sessions.find((s) => s.status === 'live')
  const resumableGrill = hasResumable(sessions, 'ideation')
  const t = tickets.length
  const done = tickets.filter((x) => x.status === 'done').length
  const failed = tickets.filter((x) => x.status === 'failed').length
  // Non-terminal tickets the burner still has to run — matches the server's
  // `burn` acceptance check (features.ts). Fix tickets from an Iterate session
  // land here as `pending`, driving the review → burn loop-back.
  const pending = tickets.filter(
    (x) => x.status !== 'done' && x.status !== 'failed' && x.status !== 'cancelled',
  ).length
  const run = latestRun(runs)
  const running = run?.status === 'running'
  const nextName = nextPhase(feature)

  // An archived feature is parked out of the pipeline (decision #8): it offers no
  // phase next-step, only a way back. Guard before the phase switch so no phase
  // surfaces grill/burn/merge actions while archived.
  if (feature.status === 'archived') {
    return {
      kick: 'ARCHIVED',
      title: 'Feature archived',
      desc: 'This feature is archived and out of the pipeline. Unarchive it to pick the work back up.',
      primary: { label: 'Unarchive', kind: 'unarchive' },
      secondary: [],
      busy: false,
    }
  }

  const canAdvance =
    !!gate.next && gate.satisfied && gate.next.id !== 'G3' && gate.next.id !== 'G5'
  const promoteLabel = nextName ? `Promote to ${PHASE_LABELS[nextName]}` : 'Promote'

  switch (feature.phase) {
    case 'ideation': {
      // Mapped features converge instead of promoting: the map's Converge button
      // (in the body, beside the fog) crosses G1 and spawns the converge session.
      // The next-step bar just narrates — it never shows a plain `advance`, which
      // would bump the phase without a session (ADR-0001 §13.6).
      if (feature.mapped) {
        return {
          kick: 'MAP',
          title: gate.satisfied ? 'Converge the map' : 'Work the frontier',
          desc: gate.satisfied
            ? 'Every waypoint is resolved — converge to draft the spec and tickets.'
            : gate.reason ?? 'Resolve the open waypoints; converge once the frontier clears.',
          primary: live ? { label: 'Jump to grill', kind: 'openGrill' } : undefined,
          secondary: [],
          busy: false,
        }
      }
      if (canAdvance) {
        return {
          kick: 'NEXT STEP',
          title: 'Promote the idea',
          desc: 'Decisions are captured — promote the idea when it feels concrete.',
          primary: { label: promoteLabel, kind: 'advance' },
          secondary: live ? [{ label: 'Back to grill', kind: 'openGrill' }] : [],
          busy: false,
        }
      }
      if (live) {
        return {
          kick: 'GRILL LIVE',
          title: 'Grill session in progress',
          desc: 'Shape the idea with Claude — decisions accumulate in Knowledge.',
          primary: { label: 'Jump to grill', kind: 'openGrill' },
          secondary: [],
          busy: false,
        }
      }
      return resumableGrill
        ? {
            kick: 'NEXT STEP',
            title: 'Pick the conversation back up',
            desc: 'The grill session ended, but its conversation is still on disk — resume it to carry on where you left off.',
            primary: { label: 'Resume grill session', kind: 'startGrill' },
            secondary: [],
            busy: false,
          }
        : {
            kick: 'NEXT STEP',
            title: 'Shape the idea with Claude',
            desc: 'Launch a grill session to shape the idea before any code is written.',
            primary: { label: 'Start grill session', kind: 'startGrill' },
            secondary: [],
            busy: false,
          }
    }
    case 'spec': {
      if (canAdvance) {
        return {
          kick: 'NEXT STEP',
          title: 'Approve the spec',
          desc: 'The spec is written — approve it to move into tickets.',
          primary: { label: 'Approve spec → tickets', kind: 'advance' },
          secondary: live ? [{ label: 'Back to grill', kind: 'openGrill' }] : [],
          busy: false,
        }
      }
      return live
        ? {
            kick: 'GRILL LIVE',
            title: 'Writing the spec',
            desc: 'The spec takes shape beside the conversation.',
            primary: { label: 'Jump to grill', kind: 'openGrill' },
            secondary: [],
            busy: false,
          }
        : {
            kick: 'NEXT STEP',
            title: 'Write the spec',
            desc: resumableGrill
              ? 'No spec yet — resume the grill conversation to draft it.'
              : 'No spec yet — open a grill session to draft it.',
            primary: {
              label: resumableGrill ? 'Resume grill' : 'Open grill',
              kind: 'startGrill',
            },
            secondary: [],
            busy: false,
          }
    }
    case 'tickets': {
      if (t > 0) {
        return {
          kick: 'NEXT STEP',
          title: 'Review & burn the tickets',
          desc: 'Each ticket is one atomic task Claude will implement. Review them, then burn.',
          primary: { label: `Burn ${t} ticket${t === 1 ? '' : 's'}`, kind: 'burn' },
          // Revisit resumes the grilling conversation to amend docs/tickets —
          // only offered when no session is live (one terminal per feature).
          secondary: live
            ? [{ label: 'Back to grill', kind: 'openGrill' }]
            : [{ label: 'Revisit', kind: 'revisit' }],
          busy: false,
        }
      }
      return {
        kick: 'WAITING',
        title: 'Waiting for tickets',
        desc: 'No tickets yet — a grill session emits them. Open a session to shape the work.',
        primary: live
          ? { label: 'Jump to grill', kind: 'openGrill' }
          : {
              label: resumableGrill ? 'Resume grill to emit tickets' : 'Open grill to emit tickets',
              kind: 'startGrill',
            },
        secondary: [],
        busy: false,
      }
    }
    case 'implementation': {
      if (running) {
        return {
          kick: 'IN PROGRESS',
          title: 'Burning tickets',
          desc: `Burning ${t} ticket${t === 1 ? '' : 's'} — ${done} done${failed ? `, ${failed} failed` : ''}.`,
          primary: { label: 'Cancel run', kind: 'cancelRun', danger: true },
          secondary: [],
          busy: true,
        }
      }
      const why =
        run?.status === 'failed'
          ? 'The run failed — resume the burn to retry.'
          : run?.status === 'cancelled'
            ? 'The run was cancelled — resume the burn to continue.'
            : 'The burn has not started — resume to run the tickets.'
      return {
        kick: 'NEXT STEP',
        title: 'Resume the burn',
        desc: why,
        primary: { label: 'Resume burn', kind: 'burn' },
        // Failed tickets are reset to pending on resume; Revisit instead opens
        // a session to amend docs and edit/cancel tickets before re-burning.
        secondary: live ? [] : [{ label: 'Revisit', kind: 'revisit' }],
        busy: false,
      }
    }
    case 'review': {
      // Test-drive toggle + Iterate stay available at review throughout. Iterate
      // opens a `revisit` session to interview the human and emit fix tickets;
      // one terminal per feature, so it's hidden while any session is live.
      const testDriveAction: NextAction = ctx.driving
        ? { label: 'Stop test drive', kind: 'testDriveStop' }
        : { label: 'Start test drive', kind: 'testDriveStart' }
      const iterate: NextAction[] = live ? [] : [{ label: 'Iterate', kind: 'revisit' }]

      // Fix tickets emitted by an Iterate session are non-terminal — while any
      // exist, the review loops back through a burn (CONTEXT decision #7): Burn is
      // promoted to primary, and Merge & ship drops to a secondary.
      if (pending > 0) {
        return {
          kick: 'NEXT STEP',
          title: 'Burn the fix tickets',
          desc: ctx.driving
            ? 'Test-driving the branch — burn the fix tickets when you’re ready.'
            : `${pending} fix ticket${pending === 1 ? '' : 's'} ready — burn to run them, then review again.`,
          primary: { label: `Burn ${pending} ticket${pending === 1 ? '' : 's'}`, kind: 'burn' },
          secondary: [{ label: 'Merge & ship', kind: 'merge' }, testDriveAction, ...iterate],
          busy: false,
        }
      }

      const desc = ctx.driving
        ? 'Test-driving the branch — merge when it looks right.'
        : failed > 0
          ? `Run finished with ${failed} failed ticket${failed === 1 ? '' : 's'} — review, then ship.`
          : 'Checks are in. Test-drive the branch, then merge to ship.'
      return {
        kick: 'NEXT STEP',
        title: ctx.driving ? 'Merge when it looks right' : 'Test drive, then ship',
        desc,
        primary: { label: 'Merge & ship', kind: 'merge' },
        secondary: [testDriveAction, ...iterate],
        busy: false,
      }
    }
    case 'shipped':
      return {
        kick: 'SHIPPED',
        title: 'Shipped to main',
        desc: 'The branch is merged and the pipeline is complete. Ask a question anytime.',
        primary: undefined,
        secondary: [{ label: 'Ask a question', kind: 'askQuestions' }],
        busy: false,
      }
  }
}

// --- the map rail (mapped ideation) ----------------------------------------

/** Split `map.md` into a `{ heading: body }` map keyed by its `## ` sections. */
export function parseMapSections(content: string): Record<string, string> {
  const out: Record<string, string> = {}
  let current: string | null = null
  const buf: string[] = []
  const flush = () => {
    if (current !== null) out[current] = buf.join('\n')
    buf.length = 0
  }
  for (const line of content.split('\n')) {
    const heading = line.match(/^##\s+(.+?)\s*$/)
    if (heading) {
      flush()
      current = heading[1]
    } else if (current !== null) {
      buf.push(line)
    }
  }
  flush()
  return out
}

export type Waypoint = FeatureFull['waypoints'][number]

export type WaypointGroupKey = 'frontier' | 'claimed' | 'blocked' | 'done'

/**
 * One waypoint as the rail renders it: the row itself plus the bits the wire
 * only carries as references — `blockedBy` is a list of seqs and
 * `originWaypointId` an id, both meaningless to a human until resolved against
 * the sibling waypoints.
 */
export interface RailWaypoint {
  waypoint: Waypoint
  /** Titles of the blockers still standing — terminal ones no longer block. */
  blockerTitles: string[]
  /** Title of the waypoint that surfaced this one, when it has an origin. */
  originTitle?: string
  /** Starts expanded in the rail: the frontier is what the human chooses between. */
  expanded: boolean
}

export interface WaypointGroup {
  key: WaypointGroupKey
  label: string
  waypoints: RailWaypoint[]
}

const WAYPOINT_GROUP_LABELS: Record<WaypointGroupKey, string> = {
  frontier: 'Frontier',
  claimed: 'Claimed',
  blocked: 'Blocked',
  done: 'Resolved / dropped',
}

/**
 * The map rail's waypoint groups (decision #4), in display order: frontier,
 * claimed, blocked, then the resolved/dropped tail. Empty groups are omitted.
 * The frontier is server-derived (open, unclaimed, every blocker terminal) and
 * is ordered by ascending seq — charting order, the closest thing to authored
 * intent. Every other group keeps the order the server sent.
 */
export function waypointGroups(
  waypoints: Waypoint[],
  frontierIds: string[],
): WaypointGroup[] {
  const front = new Set(frontierIds)
  const byId = new Map(waypoints.map((w) => [w.id, w]))
  const bySeq = new Map(waypoints.map((w) => [w.seq, w]))
  const isTerminal = (w: Waypoint) => w.status === 'resolved' || w.status === 'dropped'

  const groupOf = (w: Waypoint): WaypointGroupKey => {
    if (isTerminal(w)) return 'done'
    if (w.status === 'claimed') return 'claimed'
    return front.has(w.id) ? 'frontier' : 'blocked'
  }

  const buckets: Record<WaypointGroupKey, RailWaypoint[]> = {
    frontier: [],
    claimed: [],
    blocked: [],
    done: [],
  }
  for (const w of waypoints) {
    const key = groupOf(w)
    buckets[key].push({
      waypoint: w,
      blockerTitles: w.blockedBy
        .map((seq) => bySeq.get(seq))
        .filter((b): b is Waypoint => !!b && !isTerminal(b))
        .map((b) => b.title),
      originTitle: w.originWaypointId ? byId.get(w.originWaypointId)?.title : undefined,
      expanded: key === 'frontier',
    })
  }
  buckets.frontier.sort((a, b) => a.waypoint.seq - b.waypoint.seq)

  const order: WaypointGroupKey[] = ['frontier', 'claimed', 'blocked', 'done']
  return order
    .map((key) => ({ key, label: WAYPOINT_GROUP_LABELS[key], waypoints: buckets[key] }))
    .filter((g) => g.waypoints.length > 0)
}

import { Fragment, useEffect, useRef, useState } from 'react'
import type { EventRow, Phase } from '@runcastle/core'
import { trpc } from '../trpc'
import { useEventLog } from '../lib/events'
import { useToast } from '../lib/toast'
import { Button, DimLine, PhaseTag } from '../ui'
import type { FeatureFull } from '../lib/api'
import type { DriveState } from '../lib/workspace'
import {
  effectivePhase,
  isReadonlyView,
  latestRun,
  nextStep,
  PHASE_LABELS,
  pipelineSteps,
  REVIEW_ITERATE_KICKOFF,
  type ActionKind,
  type NextStep,
  type PipelineStep,
} from '../lib/feature-ui'
import { IconBranch } from '../icons'
import { GrillBody } from './bodies/GrillBody'
import { ReviewBody } from './bodies/ReviewBody'
import { ShippedBody } from './bodies/ShippedBody'
import { TicketsBody } from './bodies/TicketsBody'
import { RunBody } from './bodies/RunBody'

/**
 * The pipeline-first workspace (app-redesign). A selected feature fills the
 * center: a header, a clickable horizontal pipeline stepper, a single guided
 * next-step bar (one solid action), and the body for the phase currently in
 * view. Clicking an earlier step pins a read-only view of that phase; the
 * next-step bar is replaced by a read-only banner until you snap back to live.
 */
export function Workspace({
  featureId,
  viewedPhase,
  onViewPhase,
  guidance,
  mapRailCollapsed,
  onToggleMapRail,
  driving,
  onDriveChange,
}: {
  featureId: string
  viewedPhase: Phase | null
  onViewPhase: (phase: Phase | null) => void
  guidance: boolean
  mapRailCollapsed: boolean
  onToggleMapRail: () => void
  driving: DriveState | null
  onDriveChange: (d: DriveState | null) => void
}) {
  const utils = trpc.useUtils()
  const toast = useToast()
  const q = trpc.feature.get.useQuery({ id: featureId }, { refetchInterval: 1500 })
  const resumeFailed = useResumeFailedAlert(featureId)

  const invalidate = () => {
    void utils.feature.get.invalidate({ id: featureId })
    void utils.feature.list.invalidate()
  }

  const launch = trpc.feature.launchSession.useMutation({ onSuccess: invalidate, onError: (e) => toast.push(e.message) })
  const advance = trpc.feature.advance.useMutation({
    onSuccess: () => {
      invalidate()
      onViewPhase(null)
    },
    onError: (e) => toast.push(e.message),
  })
  const burn = trpc.feature.burn.useMutation({
    onSuccess: () => {
      invalidate()
      onViewPhase(null)
    },
    onError: (e) => toast.push(e.message),
  })
  const cancel = trpc.run.cancel.useMutation({
    onSuccess: () => {
      invalidate()
      toast.push('cancel requested', 'info')
    },
    onError: (e) => toast.push(e.message),
  })
  const testDrive = trpc.feature.testDrive.useMutation({ onError: (e) => toast.push(e.message) })
  const merge = trpc.feature.merge.useMutation({ onError: (e) => toast.push(e.message) })
  const unarchive = trpc.feature.unarchive.useMutation({
    onSuccess: () => {
      invalidate()
      toast.push('feature unarchived', 'success')
    },
    onError: (e) => toast.push(e.message),
  })

  if (q.isLoading) {
    return (
      <section className="workspace">
        <div className="ws-body">
          <DimLine>loading feature…</DimLine>
        </div>
      </section>
    )
  }
  // Hard error ONLY when there was never data (first load failed). When a
  // refetch fails AFTER data exists (server restart mid-session), TanStack Query
  // keeps the last-good `data` alongside `error` — keep rendering it so the
  // embedded terminal stays MOUNTED (its own reconnect strip + scrollback replay
  // depend on surviving the outage) and show a slim banner instead. The 1.5s
  // refetchInterval keeps polling through the error, so the banner self-clears
  // the moment the server is back.
  if (!q.data) {
    return (
      <section className="workspace">
        <div className="ws-body">
          <DimLine>could not load feature{q.error ? `: ${q.error.message}` : ''}</DimLine>
        </div>
      </section>
    )
  }
  const offline = !!q.error

  const full = q.data
  const feature = full.feature
  const effective = effectivePhase(feature, viewedPhase)
  const readonly = isReadonlyView(feature, effective)
  const steps = pipelineSteps(feature, effective)
  const run = latestRun(full.runs)
  const isDriving = driving?.featureId === feature.id
  const ns = nextStep(full, { driving: isDriving })
  const busy =
    launch.isPending ||
    advance.isPending ||
    burn.isPending ||
    cancel.isPending ||
    testDrive.isPending ||
    merge.isPending ||
    unarchive.isPending

  const runAction = (kind: ActionKind) => {
    switch (kind) {
      case 'startGrill':
        launch.mutate({ featureId, kind: 'ideation' })
        break
      case 'askQuestions':
        launch.mutate({ featureId, kind: 'qa' })
        break
      case 'revisit':
        launch.mutate({
          featureId,
          kind: 'revisit',
          // At review the revisit is an Iterate loop — brief the agent to read
          // the run outcome, interview about the test drive, and emit fix tickets
          // (ticket-3 kickoff override). Other phases use the default revisit line.
          kickoffLine: feature.phase === 'review' ? REVIEW_ITERATE_KICKOFF : undefined,
        })
        break
      case 'openGrill':
        onViewPhase(null)
        requestAnimationFrame(() =>
          document.getElementById('grill-term')?.scrollIntoView({ behavior: 'smooth', block: 'center' }),
        )
        break
      case 'advance':
        advance.mutate({ featureId })
        break
      case 'burn':
        burn.mutate({ featureId })
        break
      case 'cancelRun':
        if (run) cancel.mutate({ runId: run.id })
        break
      case 'unarchive':
        unarchive.mutate({ featureId })
        break
      case 'testDriveStart':
        testDrive.mutate(
          { featureId, action: 'start' },
          {
            onSuccess: (res) => {
              invalidate()
              if (res.ok && res.branch) onDriveChange({ featureId, branch: res.branch })
              else if (!res.ok) toast.push(res.deniedReason ?? 'test drive denied')
            },
          },
        )
        break
      case 'testDriveStop':
        testDrive.mutate(
          { featureId, action: 'stop' },
          {
            onSuccess: () => {
              invalidate()
              onDriveChange(null)
            },
          },
        )
        break
      case 'merge':
        merge.mutate(
          { featureId },
          {
            onSuccess: (res) => {
              invalidate()
              if (res.ok) {
                onDriveChange(null)
                toast.push('merged — feature shipped', 'success')
              } else if (res.conflict) {
                const n = res.files.length
                toast.push(
                  n > 0
                    ? `merge conflict in ${n} file${n === 1 ? '' : 's'} — resolve below and retry`
                    : 'merge conflict — resolve below and retry',
                )
              }
            },
          },
        )
        break
    }
  }

  return (
    <section className="workspace">
      <div className="ws-head">
        <div className="ws-title-row">
          <PhaseTag phase={feature.phase} />
          <span className="ws-title">{feature.title}</span>
          <span className="ws-title-spacer" />
          <button className="ws-branch" title="Copy branch name" onClick={() => copyText(feature.branch, toast)}>
            <IconBranch size={11} />
            {feature.branch}
          </button>
        </div>
        <PipelineStepper
          steps={steps}
          onView={(p) => onViewPhase(p === feature.phase ? null : p)}
        />
      </div>

      {readonly ? (
        <div className="readonly-bar">
          <span className="readonly-tag">READ-ONLY</span>
          <span>You're viewing the {PHASE_LABELS[effective]} phase.</span>
          <button className="readonly-back" onClick={() => onViewPhase(null)}>
            Back to {PHASE_LABELS[feature.phase]} →
          </button>
        </div>
      ) : (
        <NextStepBar ns={ns} guidance={guidance} busy={busy} onAction={runAction} />
      )}

      {offline && (
        <div className="ws-banner is-offline" role="status">
          <span className="ws-banner-tag">OFFLINE</span>
          <span>server unreachable — retrying…</span>
        </div>
      )}

      {resumeFailed.message && (
        <div className="ws-banner" role="alert" onClick={resumeFailed.dismiss} title="dismiss">
          <span className="ws-banner-tag">RESUME FAILED</span>
          <span>{resumeFailed.message}</span>
        </div>
      )}

      <div className="ws-body">
        <div className="ws-body-inner" key={effective}>
          <PhaseBody
            effective={effective}
            full={full}
            driving={driving}
            runId={run?.id ?? null}
            readonly={readonly}
            mapRailCollapsed={mapRailCollapsed}
            onToggleMapRail={onToggleMapRail}
          />
        </div>
      </div>
    </section>
  )
}

function PhaseBody({
  effective,
  full,
  driving,
  runId,
  readonly,
  mapRailCollapsed,
  onToggleMapRail,
}: {
  effective: Phase
  full: FeatureFull
  driving: DriveState | null
  runId: string | null
  readonly: boolean
  mapRailCollapsed: boolean
  onToggleMapRail: () => void
}) {
  switch (effective) {
    case 'ideation':
    case 'spec':
      return (
        <GrillBody
          full={full}
          effective={effective}
          mapRailCollapsed={mapRailCollapsed}
          onToggleMapRail={onToggleMapRail}
        />
      )
    case 'tickets':
      return <TicketsBody featureId={full.feature.id} readonly={readonly} />
    case 'implementation':
      return <RunBody featureId={full.feature.id} runId={runId} readonly={readonly} />
    case 'review':
      return <ReviewBody full={full} driving={driving} />
    case 'shipped':
      return <ShippedBody full={full} />
  }
}

function PipelineStepper({
  steps,
  onView,
}: {
  steps: PipelineStep[]
  onView: (phase: Phase) => void
}) {
  return (
    <div className="pipeline">
      {steps.map((s, i) => (
        <Fragment key={s.phase}>
          <button
            className={`pstep is-${s.state}${s.isViewed ? ' is-viewed' : ''}${s.clickable ? ' is-clickable' : ''}`}
            title={s.tip}
            disabled={!s.clickable}
            onClick={() => s.clickable && onView(s.phase)}
          >
            <span className="pstep-dot" />
            <span className="pstep-label">{s.label}</span>
          </button>
          {i < steps.length - 1 && (
            <span className={`pconn${s.state === 'done' ? ' is-done' : ''}`} />
          )}
        </Fragment>
      ))}
    </div>
  )
}

function NextStepBar({
  ns,
  guidance,
  busy,
  onAction,
}: {
  ns: NextStep
  guidance: boolean
  busy: boolean
  onAction: (kind: ActionKind) => void
}) {
  const kickClass =
    ns.kick === 'IN PROGRESS'
      ? 'is-progress'
      : ns.kick === 'SHIPPED'
        ? 'is-shipped'
        : ns.kick === 'WAITING'
          ? 'is-waiting'
          : ''

  return (
    <div className="nextstep">
      {ns.busy && <span className="spin-ring nextstep-spin" />}
      <div className="nextstep-main">
        <div className={`nextstep-kick ${kickClass}`}>{ns.kick}</div>
        <div className="nextstep-title">{ns.title}</div>
        {guidance && <div className="nextstep-desc">{ns.desc}</div>}
      </div>
      <div className="nextstep-actions">
        {ns.secondary.map((a, i) => (
          <Button key={i} variant="ghost" className="btn-xs" disabled={busy} onClick={() => onAction(a.kind)}>
            {a.label}
          </Button>
        ))}
        {ns.primary && (
          <Button
            variant={ns.primary.danger ? 'danger' : 'solid'}
            disabled={busy}
            onClick={() => onAction(ns.primary!.kind)}
          >
            {busy ? 'Working…' : ns.primary.label}
          </Button>
        )}
      </div>
    </div>
  )
}

/**
 * Surface `session.resume_failed` events prominently (a Resume attempt died
 * before going live — previously just a silent flicker-and-relabel). Watches
 * the feature's event log and raises a banner for ~8s on each NEW failure;
 * history replayed on mount is skipped so stale failures don't re-alert. The
 * event also stays in the inspector's activity feed permanently.
 */
function useResumeFailedAlert(featureId: string): { message: string | null; dismiss: () => void } {
  const events = useEventLog(featureId)
  const [message, setMessage] = useState<string | null>(null)
  // null until the first batch lands — everything in that batch is history.
  const lastSeenRef = useRef<number | null>(null)

  useEffect(() => {
    if (events.length === 0) return
    const maxId = events[events.length - 1].id
    if (lastSeenRef.current === null) {
      lastSeenRef.current = maxId
      return
    }
    const cutoff = lastSeenRef.current
    lastSeenRef.current = maxId
    const failed = events.filter(
      (e: EventRow) => e.id > cutoff && e.type === 'session.resume_failed',
    )
    const last = failed[failed.length - 1]
    if (last) setMessage(last.message || 'session resume failed — relaunch to continue')
  }, [events])

  useEffect(() => {
    if (!message) return
    const t = setTimeout(() => setMessage(null), 8000)
    return () => clearTimeout(t)
  }, [message])

  return { message, dismiss: () => setMessage(null) }
}

function copyText(text: string, toast: { push: (m: string, k?: 'error' | 'info' | 'success') => void }): void {
  navigator.clipboard
    .writeText(text)
    .then(() => toast.push(`copied ${text}`, 'info'))
    .catch(() => toast.push('copy failed'))
}

import { useState } from 'react'
import type { Phase } from '@runcastle/core'
import { trpc } from '../../trpc'
import { DimLine, EmptyState, SectionTitle } from '../../ui'
import type { FeatureFull } from '../../lib/api'
import {
  parseMapSections,
  waypointGroups,
  type RailWaypoint,
  type WaypointGroup,
  type WaypointGroupKey,
} from '../../lib/feature-ui'
import { useToast } from '../../lib/toast'
import { IconChevronRight, IconDoc, IconTerminal } from '../../icons'
import { DocPeek } from '../DocPeek'
import { Markdown } from '../Markdown'
import { SessionPanel } from '../SessionPanel'

/**
 * The ideation / spec phase body (app-redesign). Two panes side by side that
 * scroll independently, never one long column: a mapped feature gets the map
 * rail on the left, and the terminal — the thing the human actually types into —
 * fills everything to its right at full height. An unmapped feature is the
 * terminal pane alone (with the spec doc-card above it in the `spec` phase).
 *
 * The terminal is the real live Claude Code session, inline over the /ws PTY
 * stream. An ended session renders as the quiet ended card, which offers Resume
 * when its conversation is still on disk (see {@link SessionPanel}). With no
 * session at all the panel is an empty state — the next-step bar owns starting
 * one.
 */
export function GrillBody({
  full,
  effective,
  mapRailCollapsed,
  onToggleMapRail,
}: {
  full: FeatureFull
  effective: Phase
  mapRailCollapsed: boolean
  onToggleMapRail: () => void
}) {
  const { feature, sessions, docs } = full
  const specDoc = docs.find((d) => d.relPath.endsWith('spec.md'))
  const mapDoc = feature.mapped ? docs.find((d) => d.relPath.endsWith('map.md')) : undefined
  // Converge re-entry (recovery path): a mapped feature stranded at `spec` with
  // no live session and zero tickets means the converge session died after
  // crossing G1 — offer a subtle restart (feature.converge re-enters here).
  const hasLive = sessions.some((s) => s.status === 'live' || s.status === 'launching')
  const showConvergeResume =
    feature.mapped &&
    feature.phase === 'spec' &&
    effective === 'spec' &&
    !hasLive &&
    full.tickets.length === 0

  return (
    <div className="grill">
      {feature.mapped && (
        <MapRail
          full={full}
          relPath={mapDoc?.relPath}
          collapsed={mapRailCollapsed}
          onToggle={onToggleMapRail}
        />
      )}

      <div className="termpane">
        {effective === 'spec' && (
          <SpecCard featureId={feature.id} relPath={specDoc?.relPath} />
        )}

        {sessions.length > 0 ? (
          // The ended card's own Resume stands down while the converge-recovery
          // bar is showing — that bar relaunches the same conversation with the
          // phase framing the human needs there.
          <SessionPanel
            featureId={feature.id}
            sessions={sessions}
            showResume={!showConvergeResume}
          />
        ) : (
          <div className="grill-panel">
            <EmptyState
              icon={<IconTerminal size={16} />}
              title="No session yet"
              hint="Start a session from the bar above — you and Claude shape the idea here before any code is written."
            />
          </div>
        )}

        {showConvergeResume && <ConvergeResume featureId={feature.id} />}
      </div>
    </div>
  )
}

/**
 * Compact spec pointer: the written spec opens in a peek overlay instead of
 * dumping its full mono text into the page. Keeps the session the hero.
 */
function SpecCard({ featureId, relPath }: { featureId: string; relPath?: string }) {
  const [open, setOpen] = useState(false)
  if (!relPath) {
    return (
      <div className="doc-card is-empty">
        <IconDoc size={14} />
        <span className="doc-card-title">Spec not written yet</span>
        <span className="doc-card-hint">continue the session to draft it</span>
      </div>
    )
  }
  return (
    <>
      <button className="doc-card" onClick={() => setOpen(true)} title="View the spec">
        <IconDoc size={14} />
        <span className="doc-card-title">Specification</span>
        <span className="doc-card-meta">{relPath.split(/[\\/]/).pop()}</span>
        <span className="doc-card-open">
          View
          <IconChevronRight size={11} />
        </span>
      </button>
      {open && (
        <DocPeek featureId={featureId} relPath={relPath} title="Specification" onClose={() => setOpen(false)} />
      )}
    </>
  )
}

/**
 * Subtle recovery affordance, not a primary CTA: restart the converge session
 * for a mapped feature that crossed G1 but lost its converge session before any
 * tickets were emitted (crash / kill). The server accepts `feature.converge`
 * again at phase `spec` with no live session and zero tickets.
 */
function ConvergeResume({ featureId }: { featureId: string }) {
  const utils = trpc.useUtils()
  const toast = useToast()
  const converge = trpc.feature.converge.useMutation({
    onSuccess: () => {
      void utils.feature.get.invalidate({ id: featureId })
      void utils.feature.list.invalidate()
    },
    onError: (e) => toast.push(e.message),
  })
  return (
    <div className="converge-resume">
      <span className="converge-resume-text">
        The converge session ended before tickets were emitted.
      </span>
      <button
        type="button"
        className="btn btn-xs btn-ghost"
        disabled={converge.isPending}
        title="Restart the converge session over map.md + decisions.md"
        onClick={() => converge.mutate({ featureId })}
      >
        {converge.isPending ? 'Resuming…' : 'Resume converge'}
      </button>
    </div>
  )
}

/**
 * The four `map.md` sections, in destination-first order (SPEC §13.4). Kept in
 * sync with the server's `MAP_SECTIONS` scaffold; duplicated here rather than
 * imported so the web bundle stays free of the server's node-only knowledge
 * module.
 */
const MAP_SECTIONS = ['Destination', 'Notes', 'Not yet specified', 'Out of scope'] as const

/**
 * The mapped-ideation left rail (decision #1/#4): a fixed-width column that is
 * always visible and scrolls on its own, holding the waypoint status groups
 * first and the map doc's prose sections below them behind a disclosure that is
 * closed by default — the waypoints are the point of a map, the prose is
 * orientation you read once. The collapse toggle lives in the rail's own header
 * and shrinks it to a stub showing the frontier count; the flag is workspace
 * state, persisted globally.
 */
function MapRail({
  full,
  relPath,
  collapsed,
  onToggle,
}: {
  full: FeatureFull
  relPath?: string
  collapsed: boolean
  onToggle: () => void
}) {
  const featureId = full.feature.id
  const q = trpc.docs.read.useQuery(
    { featureId, relPath: relPath ?? 'map.md' },
    { enabled: !!relPath },
  )
  const sections = q.data ? parseMapSections(q.data.content) : {}
  const groups = waypointGroups(full.waypoints, full.frontierIds)
  const frontierCount = groups.find((g) => g.key === 'frontier')?.waypoints.length ?? 0
  // Nothing charted at all yet — one quiet card instead of stacked placeholders.
  const charted = !!relPath || full.waypoints.length > 0

  return (
    <aside className={`maprail${collapsed ? ' is-collapsed' : ''}`}>
      <div className="mr-head">
        {!collapsed && <SectionTitle>Map</SectionTitle>}
        <button
          type="button"
          className="mr-toggle"
          aria-expanded={!collapsed}
          title={collapsed ? 'Expand the map rail' : 'Collapse the map rail'}
          onClick={onToggle}
        >
          {collapsed ? '›' : '‹'}
        </button>
      </div>

      {collapsed ? (
        <button
          type="button"
          className="mr-stub"
          title={`${frontierCount} waypoint${frontierCount === 1 ? '' : 's'} on the frontier — expand the map rail`}
          onClick={onToggle}
        >
          <span className="mr-stub-count">{frontierCount}</span>
          <span className="mr-stub-label">Frontier</span>
        </button>
      ) : (
        <div className="mr-scroll">
          {q.isLoading && <DimLine>loading map…</DimLine>}

          {charted ? (
            <>
              <WaypointGroupList
                featureId={featureId}
                groups={groups}
                sessions={full.sessions}
              />
              {relPath && <MapDoc sections={sections} />}
              <ConvergeBar full={full} fog={sections['Not yet specified']?.trim()} />
            </>
          ) : (
            <div className="doc-card is-empty">
              <IconDoc size={14} />
              <span className="doc-card-title">Not charted yet</span>
              <span className="doc-card-hint">the session writes the map as you explore the idea</span>
            </div>
          )}
        </div>
      )}
    </aside>
  )
}

/** The map doc's prose, behind a disclosure that starts closed (decision #4). */
function MapDoc({ sections }: { sections: Record<string, string> }) {
  return (
    <details className="mapdoc">
      <summary className="mapdoc-summary">Map document</summary>
      {MAP_SECTIONS.map((name) => {
        const body = sections[name]?.trim()
        return (
          <section className="map-section" key={name}>
            <div className="map-section-title">{name}</div>
            {body ? <Markdown source={body} /> : <DimLine>—</DimLine>}
          </section>
        )
      })}
    </details>
  )
}

/**
 * The convergence control (ADR-0001 §13.6). Only shown on a mapped feature still
 * guarded by G1 (`all-waypoints-terminal`). When the gate is satisfiable the
 * Converge button crosses G1 and spawns a fresh converge session; while any
 * waypoint is open or claimed the button is replaced by the blocking reason and
 * an override-with-reason affordance (the seatbelt, not the cage). Remaining fog
 * (the map's "Not yet specified" prose) renders as a soft warning beside it —
 * shown, never enforced.
 */
function ConvergeBar({ full, fog }: { full: FeatureFull; fog?: string }) {
  const { feature, gate } = full
  const utils = trpc.useUtils()
  const toast = useToast()
  const [overriding, setOverriding] = useState(false)
  const [reason, setReason] = useState('')

  const converge = trpc.feature.converge.useMutation({
    onSuccess: () => {
      setOverriding(false)
      setReason('')
      void utils.feature.get.invalidate({ id: feature.id })
      void utils.feature.list.invalidate()
    },
    onError: (e) => toast.push(e.message),
  })

  // Convergence only applies while the mapped feature is still at G1 (ideation).
  if (feature.phase !== 'ideation' || gate.next?.id !== 'G1') return null

  return (
    <section className="converge-bar">
      {fog && (
        <div className="converge-fog" role="note">
          <span className="converge-fog-icon" aria-hidden="true">
            ⚑
          </span>
          <span className="converge-fog-text">
            Fog remains — still not specified: {fog}. You can converge anyway.
          </span>
        </div>
      )}

      {gate.satisfied ? (
        <button
          type="button"
          className="btn btn-solid converge-btn"
          disabled={converge.isPending}
          onClick={() => converge.mutate({ featureId: feature.id })}
        >
          {converge.isPending ? 'Converging…' : 'Converge'}
        </button>
      ) : overriding ? (
        <div className="converge-override">
          <input
            className="override-input"
            placeholder="reason to converge past open waypoints"
            value={reason}
            autoFocus
            onChange={(e) => setReason(e.target.value)}
          />
          <button
            type="button"
            className="btn btn-xs btn-solid"
            disabled={!reason.trim() || converge.isPending}
            onClick={() => converge.mutate({ featureId: feature.id, overrideReason: reason.trim() })}
          >
            Converge anyway
          </button>
          <button
            type="button"
            className="btn btn-xs btn-ghost"
            onClick={() => {
              setOverriding(false)
              setReason('')
            }}
          >
            Cancel
          </button>
        </div>
      ) : (
        <div className="converge-blocked">
          <DimLine>{gate.reason ?? 'resolve the open waypoints to converge'}</DimLine>
          <button
            type="button"
            className="btn btn-xs btn-ghost"
            onClick={() => setOverriding(true)}
          >
            Override & converge…
          </button>
        </div>
      )}
    </section>
  )
}

/**
 * The waypoint status groups (SPEC §13.6), rendered straight from the
 * `waypointGroups` derivation — membership, ordering, blocker names and lineage
 * are all decided there, so this is only markup. The resolved/dropped tail stays
 * a collapsed disclosure.
 */
function WaypointGroupList({
  featureId,
  groups,
  sessions,
}: {
  featureId: string
  groups: WaypointGroup[]
  sessions: FeatureFull['sessions']
}) {
  const utils = trpc.useUtils()
  const toast = useToast()
  const work = trpc.feature.workWaypoint.useMutation({
    onSuccess: () => {
      void utils.feature.get.invalidate({ id: featureId })
      void utils.feature.list.invalidate()
    },
    onError: (e) => toast.push(e.message),
  })
  // Serial HITL per feature (ADR-0001): only a live/launching SESSION blocks
  // spawning another terminal. A waypoint claimed by an AFK research RUN
  // (`claimedBy` = run_…) must not disable anything — research runs in parallel.
  const liveHitl = sessions.some((s) => s.status === 'live' || s.status === 'launching')

  if (groups.length === 0) {
    return (
      <div className="map-waypoints">
        <DimLine>No waypoints yet — they appear here as the map takes shape.</DimLine>
      </div>
    )
  }

  return (
    <div className="map-waypoints">
      {groups.map((g) => {
        const rows = g.waypoints.map((item) => (
          <WaypointRow
            key={item.waypoint.id}
            group={g.key}
            item={item}
            liveHitl={liveHitl}
            working={work.isPending}
            onWork={(waypointId) => work.mutate({ featureId, waypointId })}
          />
        ))
        const title = `${g.label} · ${g.waypoints.length}`
        return g.key === 'done' ? (
          <details className="wp-group wp-group-done" key={g.key}>
            <summary className="wp-group-title">{title}</summary>
            {rows}
          </details>
        ) : (
          <section className={`wp-group wp-group-${g.key}`} key={g.key}>
            <div className="wp-group-title">{title}</div>
            {rows}
          </section>
        )
      })}
    </div>
  )
}

/**
 * One waypoint, still a flat row: type badge, title, and — on the frontier — the
 * Work button (every type gets one; research starts an AFK run through the same
 * `workWaypoint` mutation, the rest spawn a terminal, and a prior release that
 * left a `lastSessionId` reads as Resume). Blocked rows name their blockers,
 * claimed rows pulse, and lineage is one "surfaced by <name>" line.
 */
function WaypointRow({
  group,
  item,
  liveHitl,
  working,
  onWork,
}: {
  group: WaypointGroupKey
  item: RailWaypoint
  liveHitl: boolean
  working: boolean
  onWork: (waypointId: string) => void
}) {
  const w = item.waypoint
  // Research is worked AFK (a run, not a terminal) — a live HITL session doesn't
  // block it. HITL types (grilling/prototype/task) spawn a terminal, so they wait
  // for the live session to end first.
  const research = w.type === 'research'
  const resuming = !research && !!w.lastSessionId
  const blockedBySession = !research && liveHitl
  // A run-claim is an AFK research run in flight — say so, instead of presenting
  // a dead row that looks like a hung session.
  const byRun = w.claimedBy?.startsWith('run_') ?? false

  return (
    <div className={`wp wp-${group}${group === 'done' ? ` wp-${w.status}` : ''}`}>
      {group === 'claimed' && <span className="wp-pulse" aria-hidden="true" />}
      <span className="wp-type">{group === 'done' ? w.status : w.type}</span>
      <span className="wp-title">{w.title}</span>

      {group === 'blocked' && item.blockerTitles.length > 0 && (
        <span className="wp-blockers">blocked by {item.blockerTitles.join(', ')}</span>
      )}
      {group === 'claimed' && byRun && <span className="wp-run-note">researching…</span>}
      {group === 'done' && w.summary && <span className="wp-summary">{w.summary}</span>}

      {group === 'frontier' && (
        <button
          type="button"
          className="btn btn-xs btn-solid wp-work"
          disabled={blockedBySession || working}
          title={
            research
              ? 'start an AFK research run on this waypoint'
              : blockedBySession
                ? 'a session is already live on this feature — end or finish it before starting another'
                : resuming
                  ? 'resume the previous session on this waypoint'
                  : 'claim this waypoint and open a session'
          }
          onClick={() => onWork(w.id)}
        >
          {resuming ? 'Resume' : 'Work'}
        </button>
      )}

      {group !== 'done' && item.originTitle && (
        <div className="wp-lineage">surfaced by {item.originTitle}</div>
      )}
    </div>
  )
}

import { describe, expect, it } from 'vitest'
import type { EventRow, TicketStatus } from '@runcastle/core'
import {
  defaultBaseBranch,
  mergeConflictKickoff,
  needsMe,
  nextStep,
  parseMapSections,
  REVIEW_ITERATE_KICKOFF,
  triage,
  triageOf,
  unresolvedMergeConflict,
  waypointGroups,
  type Waypoint,
} from '../src/lib/feature-ui'
import type { FeatureFull, FeatureListItem } from '../src/lib/api'

/**
 * Streamlining-ux ticket 2 — the New Feature form defaults Branch-from to the
 * branch the project is currently checked out on, falling back to the project
 * main branch when that checkout isn't a selectable base. Tested at the pure
 * derivation, no DOM.
 */
describe('defaultBaseBranch', () => {
  it('defaults to the current checkout when it is a selectable base', () => {
    expect(
      defaultBaseBranch({ current: 'develop', mainBranch: 'main', branches: ['main', 'develop'] }),
    ).toBe('develop')
  })

  it('defaults to main when the current checkout is main', () => {
    expect(
      defaultBaseBranch({ current: 'main', mainBranch: 'main', branches: ['main', 'develop'] }),
    ).toBe('main')
  })

  it('falls back to main on a detached HEAD (current not in the list)', () => {
    expect(
      defaultBaseBranch({ current: '', mainBranch: 'main', branches: ['main', 'develop'] }),
    ).toBe('main')
  })

  it('falls back to main when a test drive holds a feature/* checkout (excluded)', () => {
    // The picker excludes feature/* branches, so a test-drive checkout is never
    // a selectable base — the default lands on the project main branch.
    expect(
      defaultBaseBranch({ current: 'feature/x', mainBranch: 'main', branches: ['main'] }),
    ).toBe('main')
  })
})

/**
 * Reopening a terminal resumes its conversation, so the bar must say so. A
 * session row is `ended` the moment runcastle restarts (the PTY dies with the
 * server), but a row that reached `live` recorded a `ccSessionId` and the
 * launcher `--resume`s it on the next same-kind launch. The action is unchanged
 * either way — only the wording tells the human which one they'll get.
 */
describe('nextStep — Resume vs Start wording for the grill', () => {
  const grillFull = (opts: { phase?: string; sessions?: unknown[]; tickets?: unknown[] }) =>
    ({
      feature: { id: 'f1', phase: opts.phase ?? 'ideation', mapped: false, status: 'active' },
      tickets: opts.tickets ?? [],
      sessions: opts.sessions ?? [],
      runs: [],
      gate: { next: { id: 'G1' }, satisfied: false, reason: 'no decisions yet' },
    }) as unknown as FeatureFull

  const endedGrill = [{ id: 's1', status: 'ended', kind: 'ideation', ccSessionId: 'cc-1' }]

  it('says Start when the feature has never had a grill conversation', () => {
    const ns = nextStep(grillFull({}), { driving: false })
    expect(ns.primary).toEqual({ label: 'Start grill session', kind: 'startGrill' })
  })

  it('says Resume once an ended grill session left a resumable conversation', () => {
    const ns = nextStep(grillFull({ sessions: endedGrill }), { driving: false })
    expect(ns.primary).toEqual({ label: 'Resume grill session', kind: 'startGrill' })
    expect(ns.desc).toContain('still on disk')
  })

  it('keeps saying Start when the ended session never reached live (no cc id)', () => {
    const stillborn = [{ id: 's1', status: 'ended', kind: 'ideation', ccSessionId: null }]
    const ns = nextStep(grillFull({ sessions: stillborn }), { driving: false })
    expect(ns.primary?.label).toBe('Start grill session')
  })

  it('ignores a resumable session of a DIFFERENT kind (the launcher would not pick it)', () => {
    const qaOnly = [{ id: 's1', status: 'ended', kind: 'qa', ccSessionId: 'cc-qa' }]
    const ns = nextStep(grillFull({ sessions: qaOnly }), { driving: false })
    expect(ns.primary?.label).toBe('Start grill session')
  })

  it('carries the same wording into the spec and tickets phases', () => {
    expect(nextStep(grillFull({ phase: 'spec' }), { driving: false }).primary?.label).toBe(
      'Open grill',
    )
    expect(
      nextStep(grillFull({ phase: 'spec', sessions: endedGrill }), { driving: false }).primary
        ?.label,
    ).toBe('Resume grill')
    expect(nextStep(grillFull({ phase: 'tickets' }), { driving: false }).primary?.label).toBe(
      'Open grill to emit tickets',
    )
    expect(
      nextStep(grillFull({ phase: 'tickets', sessions: endedGrill }), { driving: false }).primary
        ?.label,
    ).toBe('Resume grill to emit tickets')
  })
})

/**
 * Streamlining-ux ticket 6 — the review-phase next step is a loop, not a
 * terminus: Iterate opens a revisit session (hidden while one is live), and a
 * pending fix ticket promotes Burn to primary while Merge & ship + test drive
 * stay available. Tested at the pure `nextStep` derivation.
 */
describe('nextStep at review', () => {
  const reviewFull = (opts: {
    ticketStatuses?: TicketStatus[]
    sessionLive?: boolean
  }): FeatureFull => {
    const tickets = (opts.ticketStatuses ?? []).map((status, i) => ({
      id: `t${i}`,
      status,
      commits: [],
    }))
    const sessions = opts.sessionLive ? [{ id: 's1', status: 'live', kind: 'revisit' }] : []
    return {
      feature: { id: 'f1', phase: 'review', mapped: false },
      tickets,
      sessions,
      runs: [{ id: 'r1', status: 'succeeded', startedAt: 1 }],
      gate: { next: null, satisfied: false, reason: null },
    } as unknown as FeatureFull
  }
  const labels = (as: { label: string }[]) => as.map((a) => a.label)

  it('offers Iterate and keeps Merge & ship primary when no tickets are pending', () => {
    const ns = nextStep(reviewFull({}), { driving: false })
    expect(ns.primary).toEqual({ label: 'Merge & ship', kind: 'merge' })
    expect(labels(ns.secondary)).toEqual(['Start test drive', 'Iterate'])
  })

  it('promotes Burn to primary and drops Merge & ship to secondary with a pending ticket', () => {
    const ns = nextStep(reviewFull({ ticketStatuses: ['done', 'pending'] }), { driving: false })
    expect(ns.primary).toEqual({ label: 'Burn 1 ticket', kind: 'burn' })
    expect(labels(ns.secondary)).toEqual(['Merge & ship', 'Start test drive', 'Iterate'])
  })

  it('hides Iterate while a session is live (one terminal per feature)', () => {
    const ns = nextStep(reviewFull({ sessionLive: true }), { driving: false })
    expect(labels(ns.secondary)).not.toContain('Iterate')
    // Merge & ship + test drive remain available throughout.
    expect(ns.primary?.label).toBe('Merge & ship')
    expect(labels(ns.secondary)).toEqual(['Start test drive'])
  })

  it('hides Iterate but still promotes Burn when a session is live with pending tickets', () => {
    const ns = nextStep(
      reviewFull({ ticketStatuses: ['pending'], sessionLive: true }),
      { driving: false },
    )
    expect(ns.primary).toEqual({ label: 'Burn 1 ticket', kind: 'burn' })
    expect(labels(ns.secondary)).toEqual(['Merge & ship', 'Start test drive'])
  })

  it('keeps the test-drive toggle and Merge & ship available while driving', () => {
    const ns = nextStep(reviewFull({ ticketStatuses: ['pending'] }), { driving: true })
    expect(ns.primary?.kind).toBe('burn')
    expect(labels(ns.secondary)).toEqual(['Merge & ship', 'Stop test drive', 'Iterate'])
  })

  it('exposes the review-iteration kickoff briefing for the launch override', () => {
    // The dispatch passes this verbatim as the launchSession kickoff override.
    expect(REVIEW_ITERATE_KICKOFF).toContain('REVIEW ITERATION')
    expect(REVIEW_ITERATE_KICKOFF).toContain('emit_tickets')
    expect(REVIEW_ITERATE_KICKOFF).toContain('click Burn')
  })
})

/**
 * Streamlining-ux ticket 9 — a conflicted Merge & ship is surfaced from the
 * event feed (so the conflict card survives a reload) and the resolve action
 * briefs a merge-into-feature session. Tested at the pure derivations.
 */
describe('unresolvedMergeConflict', () => {
  const ev = (id: number, type: string, data?: unknown): EventRow =>
    ({ id, projectId: 'p', ts: id, type, message: type, data }) as EventRow

  it('returns null when there is no merge.conflict event', () => {
    expect(unresolvedMergeConflict([ev(1, 'burn.started'), ev(2, 'phase.advanced')])).toBeNull()
  })

  it('reads the base branch and files off the latest merge.conflict event', () => {
    const events = [
      ev(1, 'merge.conflict', { base: 'main', files: ['a.ts'] }),
      ev(2, 'merge.conflict', { base: 'develop', files: ['x.ts', 'y.ts'] }),
    ]
    expect(unresolvedMergeConflict(events)).toEqual({ base: 'develop', files: ['x.ts', 'y.ts'] })
  })

  it('clears once a burn supersedes the conflict (loop moved on)', () => {
    const events = [
      ev(1, 'merge.conflict', { base: 'main', files: ['a.ts'] }),
      ev(2, 'burn.started', { from: 'review' }),
    ]
    expect(unresolvedMergeConflict(events)).toBeNull()
  })

  it('re-surfaces a fresh conflict after a burn cycle', () => {
    const events = [
      ev(1, 'merge.conflict', { base: 'main', files: ['a.ts'] }),
      ev(2, 'burn.started', { from: 'review' }),
      ev(3, 'merge.conflict', { base: 'main', files: ['b.ts'] }),
    ]
    expect(unresolvedMergeConflict(events)).toEqual({ base: 'main', files: ['b.ts'] })
  })

  it('tolerates a conflict event with a missing/blank file list', () => {
    expect(unresolvedMergeConflict([ev(1, 'merge.conflict', { base: 'main' })])).toEqual({
      base: 'main',
      files: [],
    })
  })
})

describe('mergeConflictKickoff', () => {
  it('names the base, feature branch, and files, and forbids advancing the phase', () => {
    const line = mergeConflictKickoff('main', 'feature/x', ['a.ts', 'b.ts'])
    expect(line).toContain('git merge main')
    expect(line).toContain('feature/x')
    expect(line).toContain('a.ts, b.ts')
    expect(line).toContain('complete_phase')
    expect(line).toContain('Merge & ship')
  })

  it('degrades gracefully when the file list is empty', () => {
    const line = mergeConflictKickoff('main', 'feature/x', [])
    expect(line).toContain('git status')
  })
})

/**
 * Ticket 7 — archive/unarchive derivations. Archived features leave the default
 * sidebar lanes (surfacing only under a show-archived toggle) and expose no
 * pipeline next-step action — only a way back (Unarchive).
 */

function listItem(over: Partial<FeatureListItem> = {}): FeatureListItem {
  return {
    id: over.id ?? 'feat_1',
    projectId: 'proj_1',
    slug: over.slug ?? 'demo',
    title: 'Demo',
    oneLiner: '',
    mapped: false,
    phase: over.phase ?? 'tickets',
    branch: 'feature/demo',
    baseBranch: 'main',
    status: over.status ?? 'active',
    createdAt: 0,
    ticketCounts: over.ticketCounts ?? {
      total: 0,
      pending: 0,
      burning: 0,
      done: 0,
      failed: 0,
      cancelled: 0,
    },
    activeRun: over.activeRun ?? false,
  } as FeatureListItem
}

function full(over: Partial<FeatureFull['feature']> = {}): FeatureFull {
  return {
    feature: { ...listItem(over as Partial<FeatureListItem>) } as FeatureFull['feature'],
    tickets: [],
    sessions: [],
    runs: [],
    docs: [],
    gate: { next: null, satisfied: false },
    waypoints: [],
    frontierIds: [],
  } as unknown as FeatureFull
}

describe('archive derivations', () => {
  it('triageOf sorts an archived feature into the archived lane', () => {
    expect(triageOf(listItem({ status: 'archived', activeRun: true }))).toBe('archived')
  })

  it('needsMe is null for archived features', () => {
    expect(needsMe(listItem({ status: 'archived', phase: 'ideation' }))).toBeNull()
  })

  it('excludes archived features from the default lanes', () => {
    const groups = triage([
      listItem({ id: 'a', status: 'active', phase: 'ideation' }),
      listItem({ id: 'b', status: 'archived' }),
    ])
    expect(groups.some((g) => g.key === 'archived')).toBe(false)
    const all = groups.flatMap((g) => g.features.map((f) => f.id))
    expect(all).not.toContain('b')
    expect(all).toContain('a')
  })

  it('surfaces archived features in a trailing lane when showArchived is on', () => {
    const groups = triage(
      [
        listItem({ id: 'a', status: 'active', phase: 'ideation' }),
        listItem({ id: 'b', status: 'archived' }),
      ],
      { showArchived: true },
    )
    const archived = groups.find((g) => g.key === 'archived')
    expect(archived?.features.map((f) => f.id)).toEqual(['b'])
    expect(groups.at(-1)?.key).toBe('archived')
  })

  it('nextStep offers only Unarchive for an archived feature (no pipeline action)', () => {
    const ns = nextStep(full({ status: 'archived', phase: 'review' }), { driving: false })
    expect(ns.primary?.kind).toBe('unarchive')
    expect(ns.secondary).toEqual([])
  })
})

/**
 * Improve-map-workflow ticket 3 — the map rail's two seams. `parseMapSections`
 * was private to the grill body; the rail and the fog warning now read one
 * implementation, so it is tested here on its own.
 */
describe('parseMapSections', () => {
  it('splits a map into its `## ` sections, keyed by heading', () => {
    const map = [
      '# Map — demo',
      '',
      'preamble that belongs to no section',
      '',
      '## Destination',
      'Ship the rail.',
      '',
      '## Out of scope',
      'The tickets body.',
    ].join('\n')
    expect(parseMapSections(map)).toEqual({
      Destination: 'Ship the rail.\n',
      'Out of scope': 'The tickets body.',
    })
  })

  it('keeps deeper headings inside their section rather than opening a new one', () => {
    const map = ['## Notes', 'intro', '### A sub-heading', 'detail'].join('\n')
    expect(parseMapSections(map)).toEqual({ Notes: 'intro\n### A sub-heading\ndetail' })
  })

  it('returns nothing for a map with no `## ` headings at all', () => {
    expect(parseMapSections('just prose\nand more prose')).toEqual({})
  })

  it('records an empty body for a heading with nothing under it', () => {
    expect(parseMapSections('## Not yet specified')).toEqual({ 'Not yet specified': '' })
  })
})

/**
 * Improve-map-workflow ticket 3 — the rail's grouping, ordering, lineage and
 * default-expanded state as a pure derivation, because this repo has no DOM
 * test environment and the rail component is kept thin over it.
 */
describe('waypointGroups', () => {
  function wp(over: Partial<Waypoint> & Pick<Waypoint, 'id' | 'seq' | 'title'>): Waypoint {
    return {
      featureId: 'feat_1',
      type: 'grilling',
      question: `what about ${over.title}?`,
      blockedBy: [],
      originWaypointId: null,
      status: 'open',
      claimedBy: null,
      lastSessionId: null,
      summary: null,
      ...over,
    } as Waypoint
  }

  const keys = (gs: ReturnType<typeof waypointGroups>) => gs.map((g) => g.key)
  const titles = (gs: ReturnType<typeof waypointGroups>, key: string) =>
    gs.find((g) => g.key === key)?.waypoints.map((r) => r.waypoint.title) ?? []

  it('returns nothing for a map with no waypoints yet', () => {
    expect(waypointGroups([], [])).toEqual([])
  })

  it('groups frontier, claimed, blocked and terminal waypoints in rail order', () => {
    const ws = [
      wp({ id: 'w1', seq: 1, title: 'resolved one', status: 'resolved', summary: 'done' }),
      wp({ id: 'w2', seq: 2, title: 'claimed one', status: 'claimed', claimedBy: 'sess_1' }),
      wp({ id: 'w3', seq: 3, title: 'open one' }),
      wp({ id: 'w4', seq: 4, title: 'blocked one', blockedBy: [2] }),
      wp({ id: 'w5', seq: 5, title: 'dropped one', status: 'dropped' }),
    ]
    const groups = waypointGroups(ws, ['w3'])
    expect(keys(groups)).toEqual(['frontier', 'claimed', 'blocked', 'done'])
    expect(titles(groups, 'frontier')).toEqual(['open one'])
    expect(titles(groups, 'claimed')).toEqual(['claimed one'])
    expect(titles(groups, 'blocked')).toEqual(['blocked one'])
    expect(titles(groups, 'done')).toEqual(['resolved one', 'dropped one'])
  })

  it('omits groups that have no waypoints', () => {
    const ws = [wp({ id: 'w1', seq: 1, title: 'only one' })]
    expect(keys(waypointGroups(ws, ['w1']))).toEqual(['frontier'])
  })

  it('orders the frontier by ascending seq whatever order the server sent', () => {
    const ws = [
      wp({ id: 'w9', seq: 9, title: 'ninth' }),
      wp({ id: 'w2', seq: 2, title: 'second' }),
      wp({ id: 'w5', seq: 5, title: 'fifth' }),
    ]
    const groups = waypointGroups(ws, ['w9', 'w2', 'w5'])
    expect(titles(groups, 'frontier')).toEqual(['second', 'fifth', 'ninth'])
  })

  it('resolves blockedBy seqs to blocker titles, dropping the ones already terminal', () => {
    const ws = [
      wp({ id: 'w1', seq: 1, title: 'already resolved', status: 'resolved' }),
      wp({ id: 'w2', seq: 2, title: 'still open' }),
      wp({ id: 'w3', seq: 3, title: 'waits on both', blockedBy: [1, 2] }),
    ]
    const groups = waypointGroups(ws, ['w2'])
    const blocked = groups.find((g) => g.key === 'blocked')?.waypoints ?? []
    expect(blocked.map((r) => r.blockerTitles)).toEqual([['still open']])
  })

  it('ignores a blockedBy seq that names no waypoint', () => {
    const ws = [wp({ id: 'w1', seq: 1, title: 'orphan edge', blockedBy: [42] })]
    const groups = waypointGroups(ws, [])
    expect(groups.find((g) => g.key === 'blocked')?.waypoints[0].blockerTitles).toEqual([])
  })

  it('names the waypoint that surfaced a later one, and leaves origin-less ones bare', () => {
    const ws = [
      wp({ id: 'w1', seq: 1, title: 'the origin', status: 'resolved' }),
      wp({ id: 'w2', seq: 2, title: 'surfaced later', originWaypointId: 'w1' }),
      wp({ id: 'w3', seq: 3, title: 'charted up front' }),
    ]
    const groups = waypointGroups(ws, ['w2', 'w3'])
    const frontier = groups.find((g) => g.key === 'frontier')?.waypoints ?? []
    expect(frontier.map((r) => r.originTitle)).toEqual(['the origin', undefined])
  })

  it('starts frontier waypoints expanded and every other group collapsed', () => {
    const ws = [
      wp({ id: 'w1', seq: 1, title: 'frontier', status: 'open' }),
      wp({ id: 'w2', seq: 2, title: 'claimed', status: 'claimed', claimedBy: 'sess_1' }),
      wp({ id: 'w3', seq: 3, title: 'blocked', blockedBy: [2] }),
      wp({ id: 'w4', seq: 4, title: 'done', status: 'resolved' }),
    ]
    const groups = waypointGroups(ws, ['w1'])
    expect(groups.map((g) => g.waypoints.map((r) => r.expanded))).toEqual([
      [true],
      [false],
      [false],
      [false],
    ])
  })

  it('labels each group for the rail header', () => {
    const ws = [
      wp({ id: 'w1', seq: 1, title: 'frontier' }),
      wp({ id: 'w2', seq: 2, title: 'done', status: 'dropped' }),
    ]
    const groups = waypointGroups(ws, ['w1'])
    expect(groups.map((g) => g.label)).toEqual(['Frontier', 'Resolved / dropped'])
  })
})

